const steps = ai && Array.isArray(ai.replay_steps) ? ai.replay_steps.filter((s) => typeof s === "string").slice(0, 6).map((s) => clean(s, 220)) : [];
const standardNote =
  "\n\n**Important:** this pull request only changes your code. A key that was already pushed stays in your git history, so revoke or replace it in the provider's dashboard. Review this change and test your app before you merge. OOPS never merges for you.";

return [
  {
    json: {
      repo: ctx.repo,
      site: ctx.site,
      branch: "oops-fix-" + Date.now(),
      findings,
      replaySteps: steps,
      prTitle: clean(ai && ai.pr_title, 100) || "OOPS: remove exposed key from code",
      prBody: (clean(ai && ai.pr_body, 1500) || "OOPS found a secret key written into your code and moved it out.") + standardNote,
      fixFiles,
      notes,
    },
  },
];

// n8n node "One item per file": the next node saves each changed file to the new branch.
const plan = $("Read answer and plan").first().json;
return plan.fixFiles.map((f) => ({
  json: {
    repo: plan.repo,
    branch: plan.branch,
    path: f.path,
    message: "OOPS: remove exposed key from " + f.path,
    contentB64: Buffer.from(f.content, "utf8").toString("base64"),
    sha: f.sha || null,
  },
}));

// n8n node "Format result": what the OOPS screen receives when keys were found.
const plan = $("Read answer and plan").first().json;
const notes = [...plan.notes];

let prUrl = null;
try {
  const pr = $("Open pull request").first().json;
  if (pr && pr.html_url) prUrl = pr.html_url;
} catch (e) {
  // the pull request step did not run
}
if (plan.fixFiles.length && !prUrl) notes.push("We couldn't open the fix pull request this time.");
if (!plan.fixFiles.length) notes.push("No code changes were made, because nothing needed fixing.");

return [{ json: { clean: false, findings: plan.findings, replaySteps: plan.replaySteps, prUrl, notes } }];

// n8n node "Clean result": no keys found. The badge is a fixed rule, never AI. It shows the date and never says "safe".
const ctx = $("Fetch and scan").first().json;
const notes = [...ctx.notes];

// If we could not read the repo or the site, we did not really check, so no badge.
if (!ctx.scanOk) {
  notes.push("We couldn't read everything we needed, so no badge was given. Please try again.");
  return [{ json: { clean: false, findings: [], notes } }];
}
return [{ json: { clean: true, checkedOn: new Date().toISOString().slice(0, 10), findings: [], notes } }];
